'use client';

import { useState, useEffect, useRef } from 'react';
import { useTranslations, useLocale } from 'next-intl';
import { useRouter } from '@/navigation';
import { Save, ArrowLeft, Plus, Move, Trash2, Layout, Palette, Type, Square, X, Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, AlignJustify, Image as ImageIcon, Layers, Link as LinkIcon } from 'lucide-react';
import { getLocalizedName } from '@/app/utils/locale';
import toast from 'react-hot-toast';

interface Snippet {
    id: string;
    name: string;
    category: string;
    htmlContent: string;
    thumbnail?: string;
}

interface Page {
    id: string;
    title: any;
    url: string;
    content: string | null;
}

interface DroppedSnippet {
    id: string; // unique instance id
    snippetId: string;
    htmlContent: string;
    name: string;
}

export default function VisualEditor({ params }: { params: Promise<{ id: string }> }) {
    const t = useTranslations('Admin');
    const commonT = useTranslations('Common');
    const router = useRouter();
    const locale = useLocale();

    const [page, setPage] = useState<Page | null>(null);
    const [snippets, setSnippets] = useState<Snippet[]>([]);
    const [droppedSnippets, setDroppedSnippets] = useState<DroppedSnippet[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [draggedSnippet, setDraggedSnippet] = useState<Snippet | null>(null);
    const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
    const [editorLocale, setEditorLocale] = useState('en');
    const [contentEn, setContentEn] = useState<DroppedSnippet[]>([]);
    const [contentAr, setContentAr] = useState<DroppedSnippet[]>([]);

    // Style Editor State
    const [activeElement, setActiveElement] = useState<HTMLElement | null>(null);
    const [activeSnippetId, setActiveSnippetId] = useState<string | null>(null);
    // Track changes to force re-renders
    const [styleVersion, setStyleVersion] = useState(0);
    const [elementText, setElementText] = useState('');

    const switchLocale = (newLocale: string) => {
        if (newLocale === editorLocale) return;
        // Save current snippets to buffer
        if (editorLocale === 'en') setContentEn(droppedSnippets);
        else setContentAr(droppedSnippets);

        // Load new snippets from buffer
        setDroppedSnippets(newLocale === 'en' ? contentEn : contentAr);
        setEditorLocale(newLocale);
    };

    const canvasRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const init = async () => {
            const { id } = await params;
            await Promise.all([fetchPage(id), fetchSnippets()]);
        };
        init();
    }, [params]);

    const fetchPage = async (id: string) => {
        try {
            const res = await fetch(`/api/pages/${id}`);
            if (res.ok) {
                const data = await res.json();
                setPage(data);
                if (data.content) {
                    try {
                        // Try parsing as JSON
                        let parsed = data.content;
                        if (typeof parsed === 'string') {
                            parsed = JSON.parse(parsed);
                        }

                        if (Array.isArray(parsed)) {
                            // Legacy: single array, assign to both or current?
                            // Assign to EN by default if array
                            setContentEn(parsed);
                            if (locale === 'en') setDroppedSnippets(parsed);
                        } else if (typeof parsed === 'object') {
                            // Localized format { en: [], ar: [] }
                            setContentEn(parsed.en || []);
                            setContentAr(parsed.ar || []);

                            // Set initial snippets based on editorLocale (which defaults to 'en' or we can sync with locale)
                            if (editorLocale === 'en') setDroppedSnippets(parsed.en || []);
                            else setDroppedSnippets(parsed.ar || []);
                        }
                    } catch (e) {
                        console.log('Content parse error', e);
                    }
                }
            }
        } catch (error) {
            console.error('Failed to fetch page', error);
        }
    };

    const fetchSnippets = async () => {
        try {
            const res = await fetch('/api/snippets');
            if (res.ok) {
                const data = await res.json();
                setSnippets(data);
            }
        } catch (error) {
            console.error('Failed to fetch snippets', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDragStart = (e: React.DragEvent, snippet: Snippet) => {
        setDraggedSnippet(snippet);
        e.dataTransfer.setData('text/plain', JSON.stringify(snippet));
        e.dataTransfer.effectAllowed = 'copy';
    };

    const handleDragOver = (e: React.DragEvent, index?: number) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'copy';
        if (typeof index === 'number') {
            setDragOverIndex(index);
        } else {
            setDragOverIndex(droppedSnippets.length);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        const snippetData = e.dataTransfer.getData('text/plain');
        if (!snippetData) return;

        try {
            const snippet: Snippet = JSON.parse(snippetData);
            const newSnippet: DroppedSnippet = {
                id: crypto.randomUUID(),
                snippetId: snippet.id,
                htmlContent: snippet.htmlContent,
                name: snippet.name
            };

            const dropIndex = dragOverIndex !== null ? dragOverIndex : droppedSnippets.length;
            setDroppedSnippets(prev => {
                const newSnippets = [...prev];
                newSnippets.splice(dropIndex, 0, newSnippet);
                return newSnippets;
            });
            // Auto-select the dropped snippet after a brief delay to allow rendering
            setTimeout(() => {
                const element = document.getElementById(`snippet-content-${newSnippet.id}`);
                if (element) {
                    // Trigger a click to select it
                    element.click();
                    // Or set active element directly if we want to bypass click logic, but click sets breadcrumbs etc.
                    // But click requires an event object.
                    // Better to just call the logic or simulate click.
                    // element.click() works if the handler is attached.
                    // In React the handler is onClick={...} so element.click() is standard DOM, but React might handle it.
                    // Actually, for "dangerouslySetInnerHTML" wrapper div, the onClick is on the wrapper.
                    // So `element` (the wrapper) .click() should bubble or trigger.
                    // But `handleContentClick` prevents propagation.
                    // Let's rely on manual setting if possible or just use click() and hope React dispatches it.
                    // React 17+ delegates to root, 16 delegates to document. click() on DOM node usually triggers React listeners.
                    // Let's try finding the wrapper and clicking it.
                    // The wrapper has id `snippet-content-${item.id}`? No, the wrapper has that ID.
                    // render: <div id={`snippet-content-${item.id}`} ... onClick={...}>
                    // So yes, clicking it works.
                }
            }, 100);
        } catch (err) {
            console.error('Drop failed', err);
        }
    };

    // Text & Style Editing Handlers
    const handleContentClick = (e: React.MouseEvent, snippetId: string) => {
        let target = e.target as HTMLElement;
        const wrapper = document.getElementById(`snippet-content-${snippetId}`);

        // Smart targeting: if we click inside a common text element (like an icon in a button), target the text element
        const smartTarget = target.closest('p, h1, h2, h3, h4, h5, h6, span, a, li, button, label, b, i, u, strong, em, small, sub, sup, td, th');
        if (smartTarget && wrapper?.contains(smartTarget)) {
            target = smartTarget as HTMLElement;
        }

        // Prevent default only if we are taking action
        e.stopPropagation();

        // If we click a different element, save the previous one first
        if (activeElement && activeElement !== target && activeSnippetId) {
            commitChanges(activeSnippetId);
            activeElement.style.outline = '';
        }

        // Set active element for styling
        if (activeElement) {
            activeElement.style.outline = ''; // Clear previous
        }

        setActiveElement(target);
        setActiveSnippetId(snippetId);
        setElementText(target.innerText);
        setStyleVersion(v => v + 1);

        // Visual cue for selection
        target.style.outline = '2px solid #3b82f6';
        target.style.outlineOffset = '2px';

        // Allow editing of text-containing elements
        const textTags = ['P', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'SPAN', 'A', 'LI', 'BUTTON', 'LABEL', 'B', 'I', 'U', 'STRONG', 'EM', 'SMALL', 'SUB', 'SUP', 'TD', 'TH', 'CAPTION', 'FIGCAPTION', 'DT', 'DD', 'ADDRESS'];
        const isContainer = ['DIV', 'SECTION', 'ARTICLE', 'ASIDE', 'FOOTER', 'HEADER', 'MAIN', 'NAV'].includes(target.tagName);

        // Prevent link navigation while editing
        if (target.tagName === 'A') {
            e.preventDefault();
        }

        if (textTags.includes(target.tagName) || (isContainer && target.children.length === 0)) {
            // Enable editing on click
            target.contentEditable = 'true';
            target.style.outline = 'none'; // UX: No outline while editing text

            // Set direction for correct cursor behavior in Arabic
            if (editorLocale === 'ar') {
                target.dir = 'rtl';
            } else {
                target.dir = 'ltr';
            }

            target.focus(); // <--- CRITICAL: Focus immediately so user can type

            // Sync changes to sidebar text area while typing
            const handleInput = () => {
                setElementText(target.innerText);
            };

            // Handle blur to save changes
            const handleBlur = () => {
                target.contentEditable = 'false';
                // target.removeAttribute('dir'); // Optional: remove to keep HTML clean? 
                // Better keep it if it's explicitly set.
                commitChanges(snippetId);

                target.removeEventListener('input', handleInput);
                target.removeEventListener('blur', handleBlur);
            };

            target.addEventListener('input', handleInput);
            target.addEventListener('blur', handleBlur);
        }
    };

    const clearSelection = () => {
        if (activeElement && activeSnippetId) {
            activeElement.style.outline = '';
            // activeElement.contentEditable = 'false'; // Ensure editing stops
            commitChanges(activeSnippetId); // Save final state

            setActiveElement(null);
            setActiveSnippetId(null);
        }
    };

    // Apply style directly to DOM without triggering React re-render of snippets
    const handleStyleChange = (property: string, value: string) => {
        if (!activeElement || !activeSnippetId) return;

        // Apply style to DOM
        activeElement.style[property as any] = value;

        // Force sidebar update to reflect new values (e.g. toggles)
        setStyleVersion(v => v + 1);

        // WE DO NOT CALL updateSnippetContent HERE
        // Changes are committed on blur or clearSelection
    };

    // Update Text Content from Sidebar
    const handleTextChange = (text: string) => {
        if (!activeElement || !activeSnippetId) return;

        activeElement.innerText = text;
        setElementText(text);

        // We don't commit immediately to avoid re-rendering entire snippet on keystroke
        // Changes are committed on blur or save or selection change
    };

    // Helper to get current computed style
    // We rely on styleVersion to force re-evaluation of this during render
    const getActiveStyle = (property: string) => {
        if (!activeElement) return '';
        // Check inline style first, then computed
        return activeElement.style[property as any] || window.getComputedStyle(activeElement)[property as any];
    };

    // Commit current DOM state to React State
    const commitChanges = (id: string) => {
        const wrapper = document.getElementById(`snippet-content-${id}`);
        if (wrapper) {
            // Clean artifacts before saving
            // We need to clone or work on string to avoid flashing the live element
            let content = wrapper.innerHTML;

            // Remove editor artifacts from the string
            // 1. contentEditable
            content = content.replace(/contenteditable="true"/g, '');
            // 2. outline style - this is inline style.
            // The outline is added to activeElement.
            // We should remove it from the string if it was captured.
            // Since we cleared outline from activeElement BEFORE calling this in some cases, it might be fine.
            // But in handleBlur, we didn't clear outline.

            // Regex to remove outline: ... ? It's hard to parse style string with regex safely.
            // Alternative: Temporarily remove outline from DOM, grab HTML, put it back.
            // If activeElement is inside wrapper:

            // We can trust the user's specific flow or just accept that we save cleaned HTML.
            // Let's try to remove the outline from the specific element if possible.
            // But we are working with `wrapper.innerHTML`.

            // Hacky clean:
            content = content.replace(/outline:\s*2px\s*solid\s*rgb\(59,\s*130,\s*246\);?/g, ''); // Blue outline
            content = content.replace(/outline-offset:\s*2px;?/g, '');

            setDroppedSnippets(prev => prev.map(s => {
                if (s.id === id) {
                    return { ...s, htmlContent: content };
                }
                return s;
            }));
        }
    };

    // NOTE: This function is replaced by commitChanges for internal use
    const updateSnippetContent = (id: string) => {
        commitChanges(id);
    };

    // Enhanced Save to clean up editor artefacts
    const handleSaveClean = async () => {
        // Deselect everything first to remove outlines and commit changes
        clearSelection();

        // Wait a tick for React/DOM to update styles
        setTimeout(() => {
            saveToBackend(droppedSnippets); // Pass current state
        }, 50);
    };

    const saveToBackend = async (snippetsToSave: DroppedSnippet[]) => {
        if (!page) return;
        setSaving(true);
        try {
            const contentToSave = {
                en: editorLocale === 'en' ? snippetsToSave : contentEn,
                ar: editorLocale === 'ar' ? snippetsToSave : contentAr
            };

            const contentJson = JSON.stringify(contentToSave);
            const res = await fetch(`/api/pages/${page.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ content: contentJson })
            });

            if (res.ok) {
                toast.success(commonT('saved'));
            } else {
                toast.error('Failed to save');
            }
        } catch (error) {
            console.error('Failed to save', error);
            toast.error('Failed to save');
        } finally {
            setSaving(false);
        }
    };

    const removeSnippet = (id: string) => {
        setDroppedSnippets(droppedSnippets.filter(s => s.id !== id));
        if (activeSnippetId === id) clearSelection();
    };

    const moveSnippet = (index: number, direction: 'up' | 'down') => {
        if (direction === 'up' && index === 0) return;
        if (direction === 'down' && index === droppedSnippets.length - 1) return;

        const newSnippets = [...droppedSnippets];
        const targetIndex = direction === 'up' ? index - 1 : index + 1;

        [newSnippets[index], newSnippets[targetIndex]] = [newSnippets[targetIndex], newSnippets[index]];
        setDroppedSnippets(newSnippets);
    };

    if (loading) return <div className="p-8 text-center">Loading editor...</div>;

    return (
        <div className="flex h-[calc(100vh-theme(spacing.16))] gap-6 -m-8 p-8 overflow-hidden">
            {/* Left Sidebar with Snippets */}
            <div className="w-64 flex flex-col bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex-shrink-0">
                <div className="p-4 border-b border-slate-100 bg-slate-50">
                    <h2 className="font-bold text-slate-900 flex items-center gap-2">
                        <Layout className="w-4 h-4 text-indigo-600" />
                        {t('snippetsLibrary')}
                    </h2>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-4">
                    {snippets.map(snippet => (
                        <div
                            key={snippet.id}
                            draggable
                            onDragStart={(e) => handleDragStart(e, snippet)}
                            className="p-4 bg-white border border-slate-200 rounded-xl cursor-move hover:border-indigo-500 hover:shadow-md transition-all group"
                        >
                            <div className="font-medium text-slate-700 mb-2">{snippet.name}</div>
                            <div className="text-xs text-slate-400 bg-slate-50 px-2 py-1 rounded inline-block">
                                {snippet.category}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Main Canvas */}
            <div className="flex-1 flex flex-col min-w-0 bg-slate-100 rounded-2xl border border-slate-200 overflow-hidden relative">
                {/* Editor Header */}
                <div className="h-16 bg-white border-b border-slate-200 flex justify-between items-center px-6 flex-shrink-0 z-10">
                    <div className="flex items-center gap-4">
                        <button onClick={() => router.back()} className="p-2 hover:bg-slate-100 rounded-lg transition-colors">
                            <ArrowLeft className="w-5 h-5 text-slate-600" />
                        </button>
                        <h1 className="font-bold text-slate-900 truncate max-w-md">{getLocalizedName(page?.title, locale) || t('untitledPage')}</h1>

                        <div className="flex items-center bg-slate-100 rounded-lg p-1 ml-4 rtl:mr-4 rtl:ml-0">
                            <button
                                onClick={() => switchLocale('en')}
                                className={`px-3 py-1 text-xs font-semibold rounded-md transition-all ${editorLocale === 'en' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                English
                            </button>
                            <button
                                onClick={() => switchLocale('ar')}
                                className={`px-3 py-1 text-xs font-semibold rounded-md transition-all ${editorLocale === 'ar' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                العربية
                            </button>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <button
                            onClick={() => window.open(`/${locale}/${page?.url || ''}`, '_blank')}
                            className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-50 rounded-lg transition-colors"
                        >
                            {commonT('preview')}
                        </button>
                        <button
                            onClick={handleSaveClean}
                            disabled={saving}
                            className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 transition-colors disabled:opacity-50"
                        >
                            <Save className="w-4 h-4" />
                            {saving ? t('saving') : commonT('saveChanges')}
                        </button>
                    </div>
                </div>

                {/* Droppable Area */}
                <div
                    ref={canvasRef}
                    onDragOver={(e) => handleDragOver(e)}
                    onClick={(e) => {
                        // If clicking directly on canvas background (not event from snippet), clear selection
                        if (e.target === canvasRef.current) {
                            clearSelection();
                        }
                    }}
                    onDrop={(e) => {
                        e.preventDefault();
                        handleDrop(e);
                    }}
                    className="flex-1 overflow-y-auto p-8 relative scroll-smooth"
                >
                    {droppedSnippets.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50/50 pointer-events-none">
                            <Move className="w-12 h-12 mb-4 opacity-50" />
                            <p className="text-lg font-medium">{t('dragDropTitle')}</p>
                            <p className="text-sm">{t('dragDropDesc')}</p>
                        </div>
                    ) : (
                        <div className="space-y-4 pb-20 max-w-5xl mx-auto">
                            {droppedSnippets.map((item, index) => (
                                <div
                                    key={item.id}
                                    className="group relative bg-white shadow-xs hover:shadow-lg transition-shadow border border-transparent hover:border-indigo-500 rounded-sm"
                                    onDragOver={(e) => {
                                        e.stopPropagation();
                                        handleDragOver(e, index);
                                    }}
                                >
                                    {/* Snippet Toolbar */}
                                    <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity bg-white shadow-sm border border-slate-200 p-1 rounded-lg z-20">
                                        <button onClick={() => moveSnippet(index, 'up')} disabled={index === 0} className="snippet-btn p-1.5 hover:bg-slate-100 rounded">↑</button>
                                        <button onClick={() => moveSnippet(index, 'down')} disabled={index === droppedSnippets.length - 1} className="snippet-btn p-1.5 hover:bg-slate-100 rounded">↓</button>
                                        <button onClick={() => removeSnippet(item.id)} className="snippet-btn p-1.5 hover:bg-red-50 text-red-500 rounded"><Trash2 className="w-4 h-4" /></button>
                                    </div>

                                    {/* Drop Indicator */}
                                    {dragOverIndex === index && (
                                        <div className="absolute -top-2 left-0 right-0 h-1 bg-indigo-500 z-30 pointer-events-none"></div>
                                    )}

                                    {/* Content Wrapper */}
                                    <div
                                        id={`snippet-content-${item.id}`}
                                        dangerouslySetInnerHTML={{ __html: item.htmlContent }}
                                        onClick={(e) => handleContentClick(e, item.id)}
                                        className="pointer-events-auto min-h-[50px]"
                                    />
                                </div>
                            ))}

                            {/* Global Drop Zone */}
                            <div
                                className={`h-32 border-2 border-dashed border-slate-300 rounded-xl flex items-center justify-center transition-colors ${dragOverIndex === droppedSnippets.length ? 'bg-indigo-50 border-indigo-400' : 'bg-slate-50/50'}`}
                                onDragOver={(e) => {
                                    e.stopPropagation();
                                    handleDragOver(e, droppedSnippets.length);
                                }}
                            >
                                <span className="text-slate-400 font-medium">{t('dropToAppend')}</span>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Right Style Editor Sidebar */}
            {activeElement && (
                <div className="w-72 flex flex-col bg-white rounded-2xl border border-slate-200 shadow-xl overflow-hidden flex-shrink-0 animate-in slide-in-from-right-10 duration-200">
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                        <h2 className="font-bold text-slate-900 flex items-center gap-2">
                            <Palette className="w-4 h-4 text-purple-600" />
                            Style Editor
                        </h2>
                        <button onClick={clearSelection} className="text-slate-400 hover:text-slate-600">
                            <X className="w-4 h-4" />
                        </button>
                    </div>

                    <div className="flex-1 overflow-y-auto p-5 space-y-6">
                        {/* Structure Navigation */}
                        <div className="mb-4 space-y-2">
                            {/* Large "Edit Section" Button if applicable */}
                            {(() => {
                                let curr: HTMLElement | null = activeElement;
                                let section: HTMLElement | null = null;
                                while (curr && curr.id !== `snippet-content-${activeSnippetId}`) {
                                    if (curr.tagName === 'SECTION' || (curr.tagName === 'DIV' && curr.parentElement?.id === `snippet-content-${activeSnippetId}`)) {
                                        section = curr;
                                        break;
                                    }
                                    curr = curr.parentElement;
                                }

                                if (section && section !== activeElement) {
                                    return (
                                        <button
                                            onClick={() => {
                                                if (activeElement?.isContentEditable) {
                                                    activeElement.contentEditable = 'false';
                                                    commitChanges(activeSnippetId!);
                                                }
                                                setActiveElement(section);
                                                section.style.outline = '2px solid #3b82f6';
                                                section.style.outlineOffset = '2px';
                                            }}
                                            className="w-full py-2 px-3 bg-indigo-50 text-indigo-600 border border-indigo-100 rounded-lg hover:bg-indigo-100 font-semibold text-sm flex items-center justify-center gap-2 transition-colors"
                                        >
                                            <Layers className="w-4 h-4" /> Edit Parent Section
                                        </button>
                                    );
                                }
                                return null;
                            })()}

                            {/* Breadcrumbs */}
                            <div className="flex flex-wrap gap-1 text-[10px] items-center px-1">
                                {(() => {
                                    const crumbs = [];
                                    let curr: HTMLElement | null = activeElement;
                                    const rootId = `snippet-content-${activeSnippetId}`;

                                    while (curr && curr.id !== rootId && crumbs.length < 5) {
                                        crumbs.unshift(curr);
                                        curr = curr.parentElement;
                                    }
                                    return crumbs.map((el, i) => (
                                        <div key={i} className="flex items-center">
                                            {i > 0 && <span className="text-slate-300 mx-1">/</span>}
                                            <button
                                                onClick={() => {
                                                    if (el !== activeElement) {
                                                        if (activeElement && activeElement.isContentEditable) {
                                                            activeElement.contentEditable = 'false';
                                                            commitChanges(activeSnippetId!);
                                                        }
                                                        setActiveElement(el);
                                                        el.style.outline = '2px solid #3b82f6';
                                                        el.style.outlineOffset = '2px';
                                                    }
                                                }}
                                                className={`hover:bg-indigo-50 px-1.5 py-0.5 rounded transition-colors uppercase font-bold tracking-wider ${el === activeElement ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500'}`}
                                            >
                                                {el.tagName.toLowerCase()}
                                            </button>
                                        </div>
                                    ));
                                })()}
                            </div>
                        </div>

                        {/* Image Editor */}
                        {activeElement.tagName === 'IMG' && (
                            <div>
                                <label className="flex items-center gap-2 text-sm font-semibold text-slate-700 mb-3">
                                    <ImageIcon className="w-4 h-4" /> Image Properties
                                </label>
                                <div className="space-y-3">
                                    <div>
                                        <label className="block text-xs text-slate-500 mb-1">Source URL</label>
                                        <input
                                            type="text"
                                            value={(activeElement as HTMLImageElement).src}
                                            onChange={(e) => {
                                                (activeElement as HTMLImageElement).src = e.target.value;
                                                setStyleVersion(v => v + 1);
                                                // Should commit eventually
                                            }}
                                            onBlur={() => commitChanges(activeSnippetId!)}
                                            className="w-full text-xs p-2 border border-slate-200 rounded bg-white"
                                            placeholder="https://..."
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs text-slate-500 mb-1">Alt Text</label>
                                        <input
                                            type="text"
                                            value={(activeElement as HTMLImageElement).alt}
                                            onChange={(e) => {
                                                (activeElement as HTMLImageElement).alt = e.target.value;
                                            }}
                                            onBlur={() => commitChanges(activeSnippetId!)}
                                            className="w-full text-xs p-2 border border-slate-200 rounded bg-white"
                                            placeholder="Description..."
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs text-slate-500 mb-1">Width / Height</label>
                                        <div className="flex gap-2">
                                            <input
                                                type="text"
                                                placeholder="Width (e.g. 100%, 200px)"
                                                value={activeElement.style.width || activeElement.getAttribute('width') || ''}
                                                onChange={(e) => handleStyleChange('width', e.target.value)}
                                                className="w-1/2 text-xs p-2 border rounded"
                                            />
                                            <input
                                                type="text"
                                                placeholder="Height"
                                                value={activeElement.style.height || activeElement.getAttribute('height') || ''}
                                                onChange={(e) => handleStyleChange('height', e.target.value)}
                                                className="w-1/2 text-xs p-2 border rounded"
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* Text Content Editor Removed as per request (Direct editing only) */}


                        {/* Typography & Color - Enhanced for Rich Text */}
                        {activeElement.tagName !== 'IMG' && (
                            <div className="space-y-6">
                                {/* Text Color - Smart (Rich Text or Element) */}
                                <div>
                                    <label className="flex items-center gap-2 text-sm font-semibold text-slate-700 mb-3">
                                        <Type className="w-4 h-4" /> Text Styling
                                    </label>

                                    {/* Color Swatches */}
                                    <div className="flex gap-2 flex-wrap mb-4">
                                        {['#000000', '#ffffff', '#ef4444', '#f59e0b', '#10b981', '#3b82f6', '#4f46e5', '#8b5cf6'].map(color => (
                                            <button
                                                key={color}
                                                onMouseDown={(e) => {
                                                    e.preventDefault(); // Keep selection
                                                    if (document.queryCommandSupported('foreColor') && window.getSelection()?.toString()) {
                                                        document.execCommand('foreColor', false, color);
                                                    } else {
                                                        handleStyleChange('color', color);
                                                    }
                                                }}
                                                className="w-8 h-8 rounded-full border border-slate-200 shadow-sm hover:scale-110 transition-transform"
                                                style={{ backgroundColor: color }}
                                                title="Text Color"
                                            />
                                        ))}
                                        <input
                                            type="color"
                                            className="w-8 h-8 p-0 border-0 rounded-full overflow-hidden cursor-pointer"
                                            onChange={(e) => handleStyleChange('color', e.target.value)}
                                        />
                                    </div>

                                    {/* Rich Text Toolbar */}
                                    <div className="flex items-center justify-between gap-2 bg-slate-100 p-1.5 rounded-lg border border-slate-200">
                                        <button
                                            onMouseDown={(e) => {
                                                e.preventDefault();
                                                if (document.queryCommandSupported('bold') && window.getSelection()?.toString()) {
                                                    document.execCommand('bold');
                                                } else {
                                                    handleStyleChange('fontWeight', activeElement.style.fontWeight === 'bold' ? 'normal' : 'bold');
                                                }
                                            }}
                                            className={`p-2 rounded hover:bg-white hover:shadow-sm transition-all ${activeElement.style.fontWeight === 'bold' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                                            title="Bold"
                                        >
                                            <Bold className="w-4 h-4" />
                                        </button>
                                        <button
                                            onMouseDown={(e) => {
                                                e.preventDefault();
                                                if (document.queryCommandSupported('italic') && window.getSelection()?.toString()) {
                                                    document.execCommand('italic');
                                                } else {
                                                    handleStyleChange('fontStyle', activeElement.style.fontStyle === 'italic' ? 'normal' : 'italic');
                                                }
                                            }}
                                            className={`p-2 rounded hover:bg-white hover:shadow-sm transition-all ${activeElement.style.fontStyle === 'italic' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                                            title="Italic"
                                        >
                                            <Italic className="w-4 h-4" />
                                        </button>
                                        <button
                                            onMouseDown={(e) => {
                                                e.preventDefault();
                                                if (document.queryCommandSupported('underline') && window.getSelection()?.toString()) {
                                                    document.execCommand('underline');
                                                } else {
                                                    handleStyleChange('textDecoration', activeElement.style.textDecoration.includes('underline') ? 'none' : 'underline');
                                                }
                                            }}
                                            className={`p-2 rounded hover:bg-white hover:shadow-sm transition-all ${activeElement.style.textDecoration.includes('underline') ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                                            title="Underline"
                                        >
                                            <Underline className="w-4 h-4" />
                                        </button>
                                    </div>

                                    {/* Alignment */}
                                    <div className="flex items-center justify-between gap-2 bg-slate-100 p-1.5 rounded-lg border border-slate-200 mt-2">
                                        <button
                                            onClick={() => handleStyleChange('textAlign', 'left')}
                                            className={`flex-1 p-2 rounded flex justify-center ${activeElement.style.textAlign === 'left' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                                        >
                                            <AlignLeft className="w-4 h-4" />
                                        </button>
                                        <button
                                            onClick={() => handleStyleChange('textAlign', 'center')}
                                            className={`flex-1 p-2 rounded flex justify-center ${activeElement.style.textAlign === 'center' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                                        >
                                            <AlignCenter className="w-4 h-4" />
                                        </button>
                                        <button
                                            onClick={() => handleStyleChange('textAlign', 'right')}
                                            className={`flex-1 p-2 rounded flex justify-center ${activeElement.style.textAlign === 'right' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                                        >
                                            <AlignRight className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* Background */}
                        <div className="space-y-4">
                            <label className="flex items-center gap-2 text-sm font-semibold text-slate-700">
                                <Square className="w-4 h-4" /> Background
                            </label>

                            {/* Bg Color */}
                            <div className="flex gap-2 flex-wrap">
                                {['transparent', '#ffffff', '#f8fafc', '#1e293b', '#fca5a5', '#93c5fd', '#c4b5fd'].map(color => (
                                    <button
                                        key={color}
                                        onClick={() => handleStyleChange('backgroundColor', color)}
                                        className="w-8 h-8 rounded-full border border-slate-200 shadow-sm hover:scale-110 transition-transform relative"
                                        style={{ backgroundColor: color === 'transparent' ? 'white' : color }}
                                        title={color}
                                    >
                                        {color === 'transparent' && (
                                            <div className="absolute inset-0 flex items-center justify-center text-red-500 font-bold overflow-hidden">
                                                <div className="w-full h-px bg-red-500 rotate-45 transform origin-center"></div>
                                            </div>
                                        )}
                                    </button>
                                ))}
                                <input
                                    type="color"
                                    className="w-8 h-8 p-0 border-0 rounded-full overflow-hidden cursor-pointer"
                                    onChange={(e) => handleStyleChange('backgroundColor', e.target.value)}
                                />
                            </div>

                            {/* Bg Image */}
                            <div className="space-y-3 p-3 bg-slate-50 rounded-lg border border-slate-200">
                                <label className="text-xs font-semibold text-slate-500 flex gap-2 items-center">
                                    <ImageIcon className="w-3 h-3" /> Background Image
                                </label>
                                <input
                                    type="text"
                                    className="w-full text-xs p-2 border border-slate-200 rounded bg-white"
                                    placeholder="https://..."
                                    value={activeElement.style.backgroundImage?.replace(/url\(['"]?(.*?)['"]?\)/, '$1') === 'none' ? '' : activeElement.style.backgroundImage?.replace(/url\(['"]?(.*?)['"]?\)/, '$1') || ''}
                                    onChange={(e) => {
                                        const val = e.target.value.trim();
                                        handleStyleChange('backgroundImage', val ? `url('${val}')` : 'none');
                                        if (val) {
                                            handleStyleChange('backgroundSize', 'cover');
                                            handleStyleChange('backgroundPosition', 'center');
                                        }
                                    }}
                                />
                                <div className="flex gap-2 text-[10px]">
                                    <button onClick={() => handleStyleChange('backgroundSize', 'cover')} className="px-2 py-1 bg-white border rounded hover:border-indigo-500 transition-colors">Cover</button>
                                    <button onClick={() => handleStyleChange('backgroundSize', 'contain')} className="px-2 py-1 bg-white border rounded hover:border-indigo-500 transition-colors">Contain</button>
                                    <button onClick={() => handleStyleChange('backgroundPosition', 'center')} className="px-2 py-1 bg-white border rounded hover:border-indigo-500 transition-colors">Center</button>
                                </div>
                            </div>
                        </div>

                        {/* Link Properties */}
                        {activeElement.tagName === 'A' && (
                            <div className="space-y-3 p-3 bg-blue-50 rounded-lg border border-blue-100">
                                <label className="text-sm font-semibold text-blue-800 flex items-center gap-2">
                                    <LinkIcon className="w-4 h-4" /> Link Properties
                                </label>
                                <div>
                                    <label className="block text-xs text-blue-600 mb-1">Target URL</label>
                                    <input
                                        type="text"
                                        value={activeElement.getAttribute('href') || ''}
                                        onChange={(e) => {
                                            activeElement.setAttribute('href', e.target.value);
                                            setStyleVersion(v => v + 1);
                                        }}
                                        onBlur={() => commitChanges(activeSnippetId!)}
                                        className="w-full text-xs p-2 border border-blue-200 rounded text-blue-900 bg-white"
                                        placeholder="https://..."
                                    />
                                </div>
                                <div className="flex items-center gap-2">
                                    <input
                                        type="checkbox"
                                        id="openInNewTab"
                                        checked={activeElement.getAttribute('target') === '_blank'}
                                        onChange={(e) => {
                                            if (e.target.checked) activeElement.setAttribute('target', '_blank');
                                            else activeElement.removeAttribute('target');
                                            setStyleVersion(v => v + 1);
                                            commitChanges(activeSnippetId!);
                                        }}
                                    />
                                    <label htmlFor="openInNewTab" className="text-xs text-blue-700 select-none cursor-pointer">Open in new tab</label>
                                </div>
                            </div>
                        )}

                        {/* Spacing */}
                        <div className="space-y-4 pt-4 border-t border-slate-100">
                            <label className="flex items-center gap-2 text-sm font-semibold text-slate-700">
                                <Move className="w-4 h-4" /> Spacing
                            </label>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs text-slate-500 mb-1">Padding</label>
                                    <input
                                        type="range" min="0" max="100" step="4"
                                        className="w-full accent-indigo-600"
                                        onChange={(e) => handleStyleChange('padding', `${e.target.value}px`)}
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 mb-1">Margin</label>
                                    <input
                                        type="range" min="0" max="100" step="4"
                                        className="w-full accent-indigo-600"
                                        onChange={(e) => handleStyleChange('margin', `${e.target.value}px`)}
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Border */}
                        <div className="space-y-4 pt-4 border-t border-slate-100">
                            <label className="flex items-center gap-2 text-sm font-semibold text-slate-700">
                                <Square className="w-4 h-4 border border-current rounded-sm" /> Border
                            </label>
                            <div className="space-y-3">
                                <div className="flex items-center gap-3">
                                    <span className="text-xs text-slate-500 w-12">Width</span>
                                    <input
                                        type="range" min="0" max="20"
                                        className="flex-1 accent-indigo-600"
                                        onChange={(e) => {
                                            handleStyleChange('borderWidth', e.target.value + 'px');
                                            if (activeElement.style.borderStyle === '') handleStyleChange('borderStyle', 'solid');
                                        }}
                                    />
                                </div>
                                <div className="flex items-center gap-3">
                                    <span className="text-xs text-slate-500 w-12">Radius</span>
                                    <input
                                        type="range" min="0" max="100"
                                        className="flex-1 accent-indigo-600"
                                        onChange={(e) => handleStyleChange('borderRadius', e.target.value + 'px')}
                                    />
                                </div>
                                <div className="flex items-center gap-3">
                                    <span className="text-xs text-slate-500 w-12">Color</span>
                                    <input
                                        type="color"
                                        className="flex-1 h-8 rounded border-0 p-0 cursor-pointer"
                                        onChange={(e) => handleStyleChange('borderColor', e.target.value)}
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
